#!/usr/bin/env python3
"""Diagnose the immutable failed R3 matched roll pair without changing its score."""
import csv,json,sys
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
from synthesize_rich_r3_roll_discrete_lqr import matrices
FILES={'baseline':ROOT/'logs/rich_R3_roll_matched_baseline_20260712_203402.csv','lqr':ROOT/'logs/rich_R3_roll_matched_lqr_20260712_203707.csv'}
def analyze(path,A,B):
 r=list(csv.DictReader(path.open(newline='')));t=np.array([float(x['t_s']) for x in r]);p=np.array([float(x['p_deg_s']) for x in r]);pre=(t>=5)&(t<9);center=p[pre].mean();pc=p-center;total=np.array([float(x['total_roll_perturbation']) for x in r]);yoke=np.array([float(x['yoke_roll_perturbation']) for x in r]);sent=np.array([float(x['sent_roll_perturbation']) for x in r]);d=np.array([float(x['disturbance_command']) for x in r]);pred=np.array([(A@np.array([float(r[i]['p_error_deg_s']),total[i],yoke[i]])+B[:,0]*yoke[i+1])[0] for i in range(len(r)-1)]);measured=np.array([float(x['p_error_deg_s']) for x in r[1:]]);active=(t[1:]>=10)&(t[1:]<18);rmse=float(np.sqrt(np.mean((pred[active]-measured[active])**2)));scale=float(np.ptp(measured[active]));cumulative={str(end):float(np.trapezoid(np.abs(pc[(t>=10)&(t<end)]),t[(t>=10)&(t<end)])) for end in (12,14,16,18)}
 return {'pre_p_mean_deg_s':float(center),'pre_p_std_deg_s':float(p[pre].std()),'active_p_std_deg_s':float(p[(t>=10)&(t<18)].std()),'pulse_nonzero_samples':int(np.sum(np.abs(d)>0)),'realized_pulse_peak':float(np.max(np.abs(d))),'peak_sent_command':float(np.max(np.abs(sent))),'sent_limit_samples':int(np.sum(np.abs(sent)>=.0002-1e-12)),'sent_to_yoke_one_sample_correlation':float(np.corrcoef(yoke[1:],sent[:-1])[0,1]),'sent_to_yoke_one_sample_rmse':float(np.sqrt(np.mean((yoke[1:]-sent[:-1])**2))),'cascade_one_step_p_rmse_deg_s':rmse,'cascade_one_step_p_nrmse':rmse/scale,'cumulative_integral_abs_p_deg':cumulative}
def main():
 m=json.loads((ROOT/'configs/rich_R3_roll_discrete_cascade.json').read_text());yt=m['yoke_to_total']['selected'];sp=m['surface_to_p']['selected'];A,B=matrices(yt['beta'][0],*yt['beta'][1:],m['total_to_surface']['static_gain'],*sp['beta']);runs={k:analyze(v,A,B) for k,v in FILES.items()};ratios={end:runs['lqr']['cumulative_integral_abs_p_deg'][end]/runs['baseline']['cumulative_integral_abs_p_deg'][end] for end in ('12','14','16','18')};out={'status':'offline_diagnosis_only','files':{k:str(v.relative_to(ROOT)) for k,v in FILES.items()},'runs':runs,'cumulative_lqr_to_baseline_integral_ratios':ratios,'frozen_score_retained':{'integral_ratio':ratios['18'],'gate_max':.70,'pass':False},'findings':['Both command paths were realized at the yoke with essentially exact one-sample tracking.','The ratio degrades as the post-pulse quiet tail is accumulated, indicating reload-specific background motion dominates the long integration window.','The baseline reached the fixed command bound while the LQR did not, so the offline zero-state baseline trajectory did not reproduce flight operating history.'],'decision':'performance failure retained; no metric relaxation, refit, or new flight authorized'};path=ROOT/'configs/rich_R3_roll_matched_pair_diagnosis.json';path.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
if __name__=='__main__':main()
